<script>
(()=>{const btn=document.getElementById('r31-ares-btn'),ico=document.getElementById('r30-ico'),status=document.getElementById('r31-ares-status');if(!btn||!ico||!status)return;const csrf=document.querySelector('input[name="_csrf"]')?.value||'';const fields={company_name:document.querySelector('[name="company_name"]'),dic:document.querySelector('[name="dic"]'),street:document.querySelector('[name="street"]'),city:document.querySelector('[name="city"]'),zip:document.querySelector('[name="zip"]')};function setStatus(t,c=''){status.textContent=t;status.className='r31-ares-status'+(c?' '+c:'')}btn.addEventListener('click',async()=>{const value=ico.value.replace(/\D/g,'');ico.value=value;if(value.length!==8){setStatus('IČO musí mít 8 číslic.','error');ico.focus();return}btn.disabled=true;btn.textContent='Načítám…';setStatus('Ověřuji firmu v ARES…');try{const fd=new FormData();fd.set('_csrf',csrf);fd.set('ico',value);const r=await fetch('/uvod/ares',{method:'POST',body:fd,headers:{'X-Requested-With':'fetch','Accept':'application/json'}});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'ARES data se nepodařilo načíst.');const d=j.data||{};if(fields.company_name&&d.company_name)fields.company_name.value=d.company_name;if(fields.dic&&d.dic)fields.dic.value=d.dic;if(fields.street&&d.street)fields.street.value=d.street;if(fields.city&&d.city)fields.city.value=d.city;if(fields.zip&&d.zip)fields.zip.value=String(d.zip).replace(/^(\d{3})(\d{2})$/,'$1 $2');setStatus('Údaje z ARES byly načteny.','ok')}catch(e){setStatus(e.message||'ARES je momentálně nedostupný.','error')}finally{btn.disabled=false;btn.textContent='Načíst z ARES'}});})();
</script>
